def verify(result):
    a = result['vars']['a']
    b = result['vars']['b']
    c = result['vars']['c']
    d = result['vars']['d']
    return int(result['correct']) == (a*d - b*c)

def verify(result):
    v = result['vars']
    return v['det_val'] > 0 and v['tr_val'] < 0 and any(opt['is_correct'] for opt in result['options'])
